#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<vector<int>> lines(n, vector<int>(2));

    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        int left = x - y;
        int right = x + y;
        lines[i][0] = left;
        lines[i][1] = right;
    }

    sort(lines.begin(), lines.end(), [](const vector<int> &a, const vector<int> &b) {
        return a[1] < b[1];
    });

    int ans = 0;
    int now = -1000000000;

    for (const vector<int> &line : lines) {
        int left = line[0];
        int right = line[1];
        if (left > now) {
            ans += 1;
            now = right;
        }
    }

    cout << ans << endl;

    return 0;
}
